## Tool Class — `ApiTools.cs`

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Retrieves a resource by its unique identifier.")]
    public async Task<string> GetResource(
        [Description("The unique resource ID to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", resourceId);
        var response = await httpClient.GetAsync($"/api/resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Creates a new resource with a name and optional description.")]
    public async Task<string> CreateResource(
        [Description("Name for the new resource")] string name,
        [Description("Optional description of the resource")] string? description,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { name, description });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync("/api/resources", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

